import React, { useState } from 'react';

const TaskForm = ({ onAddTask }) => {
  const [taskName, setTaskName] = useState('');
  const [taskDate, setTaskDate] = useState('');
  const [priority, setPriority] = useState('medium');

  const handleSubmit = (e) => {
    e.preventDefault();

    const formData = {
      task: taskName,
      date: taskDate,
      priority: priority,
      completed: false
    };

    onAddTask(formData);

    // Reset form
    setTaskName('');
    setTaskDate('');
    setPriority('medium');
  };

  return (
    <div className="card">
      <h3>Add New Task</h3>
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="taskName">Task Name:</label>
          <input 
            type="text" 
            id="taskName" 
            value={taskName} 
            onChange={(e) => setTaskName(e.target.value)} 
            required 
          />
        </div>

        <div className="form-group">
          <label htmlFor="taskDate">Date:</label>
          <input 
            type="date" 
            id="taskDate" 
            value={taskDate} 
            onChange={(e) => setTaskDate(e.target.value)} 
            required 
          />
        </div>

        <div className="form-group">
          <label htmlFor="priority">Priority:</label>
          <select 
            id="priority" 
            value={priority} 
            onChange={(e) => setPriority(e.target.value)}
          >
            <option value="low">Low</option>
            <option value="medium">Medium</option>
            <option value="high">High</option>
          </select>
        </div>

        <button type="submit" className="btn btn-primary">Add Task</button>
      </form>
    </div>
  );
};

const GoalForm = ({ onAddGoal }) => {
  const [goalName, setGoalName] = useState('');
  const [timeframe, setTimeframe] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();

    const formData = {
      name: goalName,
      timeframe: timeframe,
      completed: false
    };

    onAddGoal(formData);

    // Reset form
    setGoalName('');
    setTimeframe('');
  };

  return (
    <div className="card">
      <h3>Add New Goal</h3>
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="goalName">Goal Name:</label>
          <input 
            type="text" 
            id="goalName" 
            value={goalName} 
            onChange={(e) => setGoalName(e.target.value)} 
            required 
          />
        </div>

        <div className="form-group">
          <label htmlFor="timeframe">Timeframe:</label>
          <input 
            type="text" 
            id="timeframe" 
            value={timeframe} 
            onChange={(e) => setTimeframe(e.target.value)} 
            placeholder="e.g., 3 months, by end of year"
            required 
          />
        </div>

        <button type="submit" className="btn btn-primary">Add Goal</button>
      </form>
    </div>
  );
};

const EventForm = ({ onAddEvent }) => {
  const [eventTitle, setEventTitle] = useState('');
  const [eventDate, setEventDate] = useState('');
  const [eventTime, setEventTime] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();

    const formData = {
      title: eventTitle,
      date: eventDate,
      time: eventTime
    };

    onAddEvent(formData);

    // Reset form
    setEventTitle('');
    setEventDate('');
    setEventTime('');
  };

  return (
    <div className="card">
      <h3>Add New Event</h3>
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="eventTitle">Event Title:</label>
          <input 
            type="text" 
            id="eventTitle" 
            value={eventTitle} 
            onChange={(e) => setEventTitle(e.target.value)} 
            required 
          />
        </div>

        <div className="form-group">
          <label htmlFor="eventDate">Date:</label>
          <input 
            type="date" 
            id="eventDate" 
            value={eventDate} 
            onChange={(e) => setEventDate(e.target.value)} 
            required 
          />
        </div>

        <div className="form-group">
          <label htmlFor="eventTime">Time:</label>
          <input 
            type="time" 
            id="eventTime" 
            value={eventTime} 
            onChange={(e) => setEventTime(e.target.value)} 
            required 
          />
        </div>

        <button type="submit" className="btn btn-primary">Add Event</button>
      </form>
    </div>
  );
};

const ItemForms = ({ activeForm, onAddItem }) => {
  return (
    <div>
      {activeForm === 'task' && <TaskForm onAddTask={(data) => onAddItem('tasks', data)} />}
      {activeForm === 'goal' && <GoalForm onAddGoal={(data) => onAddItem('goals', data)} />}
      {activeForm === 'event' && <EventForm onAddEvent={(data) => onAddItem('events', data)} />}
    </div>
  );
};

export default ItemForms;
